def link_dependencias(apps, schema_editor):
    """Crea una dependencia por cada texto de dependencia existente y la enlaza al perfil."""
    Profile = apps.get_model('core', 'Profile')
    Dependencia = apps.get_model('core', 'Dependencia')
    for profile in Profile.objects.all():
        name = profile.department.strip()
        if not name:
            continue
        dependencia = Dependencia.objects.filter(name__iexact=name).first() or Dependencia.objects.create(name=name)
        profile.dependencia = dependencia
        profile.save(update_fields=['dependencia'])


